<?php
/** Proof — JSON mode (spec "Proof" 7): every slice 8 handler under a signed action token answers {ok, did, location}; 422 {error:{code invalid, errors[], fields{}}}; the screens answer JSON; the registry reads 5 actions and 5 screens. */
require __DIR__ . '/lib.php';
ensure_year(as_member(1)); ar_fixture();
$owner = ['X-Action-Token: ' . person_token(1)]; $bea = ['X-Action-Token: ' . person_token(27)]; $vera = ['X-Action-Token: ' . person_token(26)];
$wrong = []; $count = 0;
$call = function (string $label, string $path, array $form, array $h) use (&$wrong, &$count): array {
    [$c, $b] = act_token($path, $form, $h);
    $count++;
    if ($c !== 200 || !($b['ok'] ?? false) || !isset($b['did']) || !isset($b['location'])) { $wrong[] = "$label $c " . msg($b); }
    return $b;
};
echo "1. Every action\n";
$doc = ['memo' => 'SMOKE json', 'lines' => [['account' => '6200', 'debit' => '25.00'], ['account' => '1010', 'credit' => '25.00']]];
$b = $call('recurring_save (add)', '/settings/recurring/save.php', ['name' => 'SMOKE JSON template', 'kind' => 'journal', 'cadence' => 'weekly', 'every_n' => 2, 'next_date' => '2026-11-02', 'template' => json_encode($doc)], $owner);
$t = (int) ($b['record_id'] ?? 0);
ok($t > 0 && ($b['recurring_template_id'] ?? 0) === $t && str_starts_with($b['location'], '/settings/recurring/' . $t), 'recurring_save answers the new template\'s id and where it lives');
$b = $call('recurring_save (partial)', '/settings/recurring/save.php', ['template' => $t, '_partial' => 1, 'name' => 'SMOKE JSON renamed'], $owner);
ok(tpl_row($t)['name'] === 'SMOKE JSON renamed' && tpl_row($t)['cadence'] === 'weekly' && (int) tpl_row($t)['every_n'] === 2 && count(json_decode(tpl_row($t)['template'], true)['lines']) === 2, 'an agent\'s partial update sends the record and what changes: the rest (cadence, every, the lines) is kept');
$b = $call('recurring_toggle', '/settings/recurring/toggle.php', ['template' => $t, 'active' => 'no'], $owner);
ok(($b['active'] ?? null) === false && !tpl_row($t)['active'], 'recurring_toggle answers the new state');
$call('recurring_toggle (on)', '/settings/recurring/toggle.php', ['template' => $t, 'active' => 'yes'], $owner);
$b = $call('recurring_run', '/settings/recurring/run.php', ['template' => $t], $bea);
ok(($b['status'] ?? '') === 'drafted' && ($b['record_type'] ?? '') === 'journal_entry' && (int) ($b['record_id'] ?? 0) > 0 && ($b['run_date'] ?? '') === '2026-11-02' && str_starts_with($b['location'], '/journal/'), 'recurring_run answers what it drafted, its type and id, the date, and where to open it');
ok(tpl_row($t)['next_date'] === '2026-11-16', 'every 2 weeks: the schedule is now 2026-11-16');
$b = $call('morning_note_send', '/settings/agents/morning-note.php', ['body' => 'SMOKE note', 'to_member' => 28], $bea);
ok(($b['to_member_id'] ?? 0) === 28 && ($b['length'] ?? 0) === 10, 'morning_note_send answers the recipient and the length');
$b = $call('recurring_delete', '/settings/recurring/delete.php', ['template' => $t], $owner);
ok(!tpl_row($t), 'recurring_delete');
ok($wrong === [], "$count handlers answer {ok, did, location}" . ($wrong ? ' — wrong: ' . implode('; ', $wrong) : ''));
echo "2. Refusals\n";
[$c, $b] = act_token('/settings/recurring/save.php', ['name' => '', 'kind' => 'journal', 'cadence' => 'daily', 'next_date' => 'soon', 'template' => '{}'], $owner);
ok($c === 422 && ($b['error']['code'] ?? '') === 'invalid' && count(fields($b)) >= 3 && isset(fields($b)['name'], fields($b)['cadence'], fields($b)['next_date']) && count($b['error']['errors']) === count(fields($b)), 'a bad form: 422 {error: {code invalid, errors[], fields{name, cadence, next_date}}}');
[$c, $b] = act_token('/settings/recurring/save.php', ['name' => 'SMOKE no doc', 'kind' => 'bill', 'next_date' => '2026-11-02', 'template' => json_encode(['lines' => []])], $owner);
ok($c === 422 && isset(fields($b)['lines']) && str_contains(msg($b), 'Line 1'), 'a template with no lines: 422 naming Line 1');
[$c, $b] = act_token('/settings/recurring/run.php', [], $bea);
ok($c === 422 && str_contains(msg($b), 'Say which template'), 'no template named: 422 in words');
[$c, $b] = act_token('/settings/recurring/run.php', ['template' => 999999], $bea);
ok($c === 404, 'an unknown template: 404');
[$tt, $mb] = mk_template('journal', 'SMOKE Maybe', $doc);
[$c, $b] = act_token('/settings/recurring/toggle.php', ['template' => (int) $mb['record_id'], 'active' => 'maybe'], $owner);
ok($c === 422, 'a bad yes/no: 422');
[$c, $b] = act_token('/settings/recurring/delete.php', ['template' => 1], $vera);
ok($c === 403 && ($b['error']['code'] ?? '') !== '', 'a Viewer: 403 with an error code');
echo "3. The screens\n";
$o = as_member(1);
[$c, $d] = screen($o, '/settings/recurring/');
ok($c === 200 && isset($d['templates'], $d['filters'], $d['may']), 'recurring-list answers {templates, filters, may}');
[$tt, $b] = mk_template('journal', 'SMOKE Shown', $doc);
[$c, $d] = screen($o, '/settings/recurring/' . (int) $b['record_id']);
ok($c === 200 && ($d['template']['kind'] ?? '') === 'journal' && isset($d['template']['runs']) && isset($d['template']['template']['lines']) && !isset($d['template']['created_by']), 'recurring-view answers the template, its document and runs (a whitelist)');
[$c, $d] = screen($o, '/settings/recurring/' . (int) $b['record_id'] . '/edit');
ok($c === 200 && ($d['template']['name'] ?? '') === 'SMOKE Shown', 'recurring-edit answers the template');
[$c, $d] = screen($o, '/settings/recurring/new?kind=bill');
ok($c === 200 && ($d['kind'] ?? '') === 'bill' && in_array('quarterly', $d['cadences'], true), 'recurring-add answers the kind and the cadences');
ok(screen($o, '/settings/recurring/999999')[0] === 404, 'an unknown template page is 404');
echo "4. The registry\n";
$reg = json_decode((string) file_get_contents(dirname(__DIR__, 3) . '/mcp/action_registry.json'), true);
$acts = ['recurring_save', 'recurring_toggle', 'recurring_run', 'recurring_delete', 'morning_note_send'];
ok(count(array_filter($acts, fn ($a) => ($reg['actions'][$a]['built'] ?? false) === true)) === 5, 'all five actions read built in the registry');
ok(count(array_filter(['recurring-list', 'recurring-add', 'recurring-edit', 'recurring-view'], fn ($s) => ($reg['screens'][$s]['built'] ?? false) === true)) === 4, 'the four recurring screens read built');
ok(($reg['actions']['recurring_save']['approval'] ?? '') === 'other' && ($reg['actions']['recurring_delete']['approval'] ?? '') === 'deletion' && ($reg['actions']['recurring_run']['approval'] ?? null) === null, 'save and toggle pause an agent as other, delete as deletion; run and the morning note do not');
finish();
